KEY_CACHE_ABSMAX = 35.222347259521484
# 来源：parser_output/value_cache.bin，fp32，4194304 元素，2026-09-28 提取
VALUE_CACHE_ABSMAX = 38.6334114074707


# 图入口的角色 -> 它自己那份标定常数。图内中间激活不在这张表里，走
# `activation_for`（甲方只导出了入口那一份 hidden state）。
_CALIB_BY_ROLE = {
    "cos": COS_EMBEDDING,
    "sin": SIN_EMBEDDING,
    "mask": ATTENTION_MASK,
    "kv_position": CACHE_POSITION,
}


def calibration_for_role(role: str, numel: int) -> np.ndarray:
    """按图入口的角色取它自己那份标定常数。

    四个入口（cos / sin / mask / kv_position）各有一份甲方标定文件，内容互不
    相同，不能一律拿 hidden state 平铺顶上——那样 cos 与 sin 会变成同一份，
    kv_position 这种位置索引会变成噪声（评审 r7 问题 1）。

    按 decode 槽位导出时 numel 与常数长度恰好相等（实测 cos/sin 128、
    mask 1024、kv_position 96），此时内容与甲方参考逐字节相同。长度不等的
    只有小图夹具（不重写槽位，边宽按导出图算），同 `activation_for` 平铺/截断。

    入参 role：`pim_calib_role`，由 from_fx 建边界缓冲节点时标上。
    入参 numel：该缓冲的元素数。
    返回：原始 dtype、长度为 numel 的数组（调用方再按声明的 dtype 转换）。
    """
    if numel <= 0:
        raise ValueError(f"标定常数的元素数必须为正，收到 {numel}")
    values = _CALIB_BY_ROLE[role]
    if values.size == numel:
        return values
    repeats = -(-numel // values.size)
    return np.tile(values, repeats)[:numel]


def activation_for(numel: int) -> np.ndarray:
    """按元素数取一份标定激活，dtype 为 fp16。

    DQ 四相只用到输入的逐组 absmax（phase0 = 2·absmax），所以标定只需提供
    「非零且量级合理」的激活。numel == 4096 直接返回内置 hidden_states；
    其余长度由它平铺/截断得到——甲方只导出了图入口那一份 hidden state，
    图内各节点的中间激活它并未提供，而判据只要求形式合法。

    入参 numel：该 DQ 节点的元素数，来自 spec.numel（编译期槽位口径，
                不是导出图的 seq_len）。
    返回：shape 为 (numel,) 的 fp16 数组，保证逐元素非零。
    """
    if numel <= 0:
        raise ValueError(f"标定激活的元素数必须为正，收到 {numel}")
    base = HIDDEN_STATES.astype(np.float16)
    if numel == base.size:
        return base
    repeats = -(-numel // base.size)
    return np.tile(base, repeats)[:numel]


# int8 对称量化的正向满量程。KV cache 的 scale 按 absmax/127 算。
INT8_FULL_SCALE = 127


def kv_cache_scale(*, is_key: bool) -> float:
    """K 或 V cache 的量化 scale，按标定 absmax 算。

    进出同一块 cache 共用这一个 scale（写进去的 quantize 与读出来的
    dequantize 是同一个常量），所以 KV_Cache_DMA、Split、v_proj 三处都从
    这里取，不各算一份。

    **不复现甲方的 0.0458939 / 0.00261151**：那两个是甲方真实模型标定出的
    定值，实测无法从标定数据反推（数据 absmax 是其量程的 6 倍 / 116 倍，
    absmax/127、/128、各档分位数全部试过无一命中）。按 absmax 算的结果自洽、
    非 1.0、反量化不除零、int8 不饱和。
    """
    absmax = KEY_CACHE_ABSMAX if is_key else VALUE_CACHE_ABSMAX
    return absmax / INT8_FULL_SCALE

